import React, { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { Text, Sparkles, Sphere, MeshDistortMaterial } from '@react-three/drei';
import * as THREE from 'three';

const WorldSentaient = ({ position, rotation, visible }) => {
  const logoRef = useRef();
  const auraRef = useRef();
  
  useFrame((state) => {
    if (logoRef.current) {
      // Gentle, elegant floating motion
      logoRef.current.position.y = Math.sin(state.clock.elapsedTime * 0.5) * 20;
    }
    if (auraRef.current) {
      auraRef.current.rotation.y += 0.005;
      auraRef.current.rotation.z += 0.002;
    }
  });

  return (
    <group visible={visible} position={position} rotation={rotation}>
      
      {/* Background Ambience */}
      <mesh>
        <sphereGeometry args={[1500, 32, 32]} />
        <meshBasicMaterial color="#020510" side={THREE.BackSide} />
      </mesh>

      <group ref={logoRef}>
        {/* Pure Elegance Glowing Text */}
        <Text 
          position={[0, 0, 50]} 
          fontSize={250} 
          color="#ffffff" 
          outlineWidth={0.05} 
          outlineColor="#0088ff" 
          font="/fonts/Inter-Bold.woff"
          anchorX="center"
          anchorY="middle"
        >
          S E N T A I E N T
        </Text>
        
        {/* Core philosophy text */}
        <Text 
          position={[0, -180, 50]} 
          fontSize={45} 
          color="#00ffff" 
          opacity={0.9}
          transparent
          anchorX="center"
          anchorY="middle"
          letterSpacing={0.3}
        >
          AUTONOMOUS BUSINESS PILLARS
        </Text>

        {/* Ethereal Glow Behind Logo */}
        <Sphere ref={auraRef} args={[300, 64, 64]} position={[0, 0, -50]}>
          <MeshDistortMaterial 
            color="#0066ff" 
            emissive="#0044ff"
            emissiveIntensity={2} 
            distort={0.4} 
            speed={2} 
            roughness={0.2}
            transparent
            opacity={0.6}
          />
        </Sphere>
        
        {/* Inner intense core */}
        <Sphere args={[150, 32, 32]} position={[0, 0, -40]}>
          <meshBasicMaterial color="#ffffff" transparent opacity={0.8} />
        </Sphere>

        {/* Elegant Particles */}
        <Sparkles count={400} scale={1500} size={15} speed={0.4} opacity={0.6} color="#00ffff" position={[0, 0, 0]} />
        <Sparkles count={200} scale={1000} size={25} speed={0.2} opacity={0.8} color="#ffffff" position={[0, 0, 50]} />
      </group>

      <ambientLight intensity={0.5} color="#002244" />
      <pointLight position={[0, 0, 200]} intensity={3} color="#00aaff" distance={1000} />

    </group>
  );
};

export default WorldSentaient;
