import React, { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import { Text, Sparkles } from '@react-three/drei';
import * as THREE from 'three';

const Campfire = ({ position }) => {
  const fireRef = useRef();
  
  useFrame((state) => {
    if (fireRef.current) {
      fireRef.current.rotation.y = state.clock.elapsedTime * 2;
      fireRef.current.scale.y = 1 + Math.sin(state.clock.elapsedTime * 10) * 0.1;
    }
  });

  return (
    <group position={position}>
      {/* Logs */}
      <mesh position={[0, 2, 0]} rotation={[Math.PI/2, 0, 0]}>
        <cylinderGeometry args={[2, 2, 20, 8]} />
        <meshStandardMaterial color="#3e2723" roughness={0.9} />
      </mesh>
      <mesh position={[0, 2, 0]} rotation={[Math.PI/2, Math.PI/4, 0]}>
        <cylinderGeometry args={[2, 2, 20, 8]} />
        <meshStandardMaterial color="#3e2723" roughness={0.9} />
      </mesh>
      <mesh position={[0, 2, 0]} rotation={[Math.PI/2, -Math.PI/4, 0]}>
        <cylinderGeometry args={[2, 2, 20, 8]} />
        <meshStandardMaterial color="#3e2723" roughness={0.9} />
      </mesh>

      {/* The Fire Geometry */}
      <mesh ref={fireRef} position={[0, 10, 0]}>
        <coneGeometry args={[10, 20, 8]} />
        <meshStandardMaterial 
          color="#ff4400" 
          emissive="#ff2200" 
          emissiveIntensity={2} 
          transparent 
          opacity={0.8} 
          wireframe 
        />
      </mesh>

      {/* Sparks */}
      <Sparkles count={50} scale={20} size={10} speed={2} opacity={1} color="#ff8800" position={[0, 15, 0]} />

      {/* Fire Light */}
      <pointLight color="#ff6600" intensity={5} distance={500} position={[0, 10, 0]} />
    </group>
  );
};

const Crowd = ({ count = 100, targetPosition }) => {
  const groupRef = useRef();

  // Initialize random positions in a wide circle around the target
  const avatars = useMemo(() => {
    const temp = [];
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      // Start between 300 and 800 units away from the fire
      const radius = 300 + Math.random() * 500;
      
      const x = targetPosition[0] + Math.cos(angle) * radius;
      const z = targetPosition[2] + Math.sin(angle) * radius;
      
      // Target radius to stop at (around the fire)
      const targetRadius = 50 + Math.random() * 100;
      const targetX = targetPosition[0] + Math.cos(angle) * targetRadius;
      const targetZ = targetPosition[2] + Math.sin(angle) * targetRadius;

      const colors = ["#00ffff", "#ff00ff", "#00ff00", "#ffffff"];
      const color = colors[Math.floor(Math.random() * colors.length)];

      temp.push({ startX: x, startZ: z, targetX, targetZ, color, speed: 0.5 + Math.random() });
    }
    return temp;
  }, [count, targetPosition]);

  useFrame((state) => {
    // Loop the walk animation based on elapsed time
    // t goes from 0 to 1 over 10 seconds, then resets
    const loopDuration = 15.0;
    const t = (state.clock.elapsedTime % loopDuration) / loopDuration;

    if (groupRef.current) {
      groupRef.current.children.forEach((child, i) => {
        const data = avatars[i];
        if (!data) return;
        
        // Easing function for walking toward the fire
        // They walk toward the fire, hang out, then snap back
        let progress = t * 2.0; // Walk for half the loop
        if (progress > 1) progress = 1; // Stay at target for the rest
        
        // Add a slight bounce to the Y position for walking
        const isWalking = progress < 1;
        const walkBounce = isWalking ? Math.abs(Math.sin(state.clock.elapsedTime * 10 * data.speed)) * 2 : 0;
        
        child.position.x = THREE.MathUtils.lerp(data.startX, data.targetX, progress);
        child.position.z = THREE.MathUtils.lerp(data.startZ, data.targetZ, progress);
        child.position.y = walkBounce;
      });
    }
  });

  return (
    <group ref={groupRef}>
      {avatars.map((data, i) => (
        <group key={i} position={[data.startX, 0, data.startZ]}>
          {/* Torso */}
          <mesh position={[0, 8, 0]}>
            <boxGeometry args={[4, 10, 4]} />
            <meshStandardMaterial color={data.color} emissive={data.color} emissiveIntensity={0.5} wireframe />
          </mesh>
          {/* Head */}
          <mesh position={[0, 15, 0]}>
            <sphereGeometry args={[2, 8, 8]} />
            <meshStandardMaterial color={data.color} emissive={data.color} emissiveIntensity={1} wireframe />
          </mesh>
        </group>
      ))}
    </group>
  );
};

const WorldIcebreaker = ({ position, rotation, visible }) => {
  

  return (
    <group visible={visible} position={position} rotation={rotation}>
      
      {/* Ice Cavern Floor */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -200, 0]}>
        <planeGeometry args={[3000, 3000]} />
        <meshStandardMaterial color="#001133" roughness={0.1} metalness={0.8} />
      </mesh>
      
      {/* Cavern Walls (Cylinder with normals flipped) */}
      <mesh position={[0, 0, -500]}>
        <cylinderGeometry args={[1500, 1500, 2000, 32, 1, true]} />
        <meshStandardMaterial color="#002244" roughness={0.3} metalness={0.8} side={THREE.BackSide} wireframe />
      </mesh>

      {/* The Central Campfire */}
      <Campfire position={[0, -200, -500]} />

      {/* The Crowd of people congregating around the fire */}
      <Crowd count={150} targetPosition={[0, -200, -500]} />

      {/* Ambient Blue Ice Light */}
      <ambientLight intensity={0.5} color="#0044ff" />
      <pointLight position={[0, 500, -500]} intensity={2} color="#00ffff" distance={2000} />

      <Text 
        position={[0, 300, -500]} 
        fontSize={150} 
        color="#ffffff" 
        outlineWidth={0.03} 
        outlineColor="#00ffff" 
        font="/fonts/Inter-Bold.woff"
      >
        ICEBREAKER
      </Text>
      
      <Text 
        position={[0, 200, -500]} 
        fontSize={40} 
        color="#00ffff" 
      >
        THE REAL-WORLD SOCIAL PROTOCOL
      </Text>

    </group>
  );
};

export default WorldIcebreaker;
