import React, { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { Text } from '@react-three/drei';
import * as THREE from 'three';

const Bookcase = ({ position, rotation }) => {
  return (
    <group position={position} rotation={rotation}>
      {/* Bookshelf Frame */}
      <mesh position={[0, 100, -10]}>
        <boxGeometry args={[150, 200, 20]} />
        <meshStandardMaterial color="#3e2723" roughness={0.9} metalness={0.1} />
      </mesh>
      
      {/* Shelves */}
      {[20, 60, 100, 140, 180].map((y, i) => (
        <mesh key={i} position={[0, y, 0]}>
          <boxGeometry args={[140, 2, 20]} />
          <meshStandardMaterial color="#4e342e" roughness={0.8} />
        </mesh>
      ))}

      {/* Books (Procedural look) */}
      {[20, 60, 100, 140].map((shelfY, shelfIdx) => {
        const books = [];
        for (let i = 0; i < 15; i++) {
          const width = 2 + Math.random() * 4;
          const height = 12 + Math.random() * 6;
          const xPos = -60 + i * (width + 1) + Math.random() * 20;
          if (xPos > 60) continue;
          
          const colors = ["#8b0000", "#1a237e", "#1b5e20", "#3e2723", "#000000"];
          const bookColor = colors[Math.floor(Math.random() * colors.length)];
          
          books.push(
            <mesh key={`${shelfIdx}-${i}`} position={[xPos, shelfY + height/2 + 1, 0]}>
              <boxGeometry args={[width, height, 15]} />
              <meshStandardMaterial color={bookColor} metalness={0.2} roughness={0.7} />
              {/* Gold foil lines on spine */}
              <mesh position={[0, 0, 7.6]}>
                <boxGeometry args={[width * 0.8, height * 0.8, 0.1]} />
                <meshStandardMaterial color="#d4af37" emissive="#d4af37" emissiveIntensity={0.5} />
              </mesh>
            </mesh>
          );
        }
        return books;
      })}
    </group>
  );
};

const LibraryDesk = ({ position, rotation }) => {
  return (
    <group position={position} rotation={rotation}>
      {/* Mahogany Desk */}
      <mesh position={[0, 30, 0]}>
        <boxGeometry args={[120, 5, 60]} />
        <meshStandardMaterial color="#27140c" roughness={0.3} metalness={0.4} />
      </mesh>
      {/* Desk Legs */}
      <mesh position={[-50, 15, 0]}>
        <boxGeometry args={[10, 30, 50]} />
        <meshStandardMaterial color="#1a0d07" roughness={0.5} />
      </mesh>
      <mesh position={[50, 15, 0]}>
        <boxGeometry args={[10, 30, 50]} />
        <meshStandardMaterial color="#1a0d07" roughness={0.5} />
      </mesh>

      {/* Banker's Lamp Base */}
      <mesh position={[0, 35, -15]}>
        <cylinderGeometry args={[3, 4, 2, 16]} />
        <meshStandardMaterial color="#d4af37" metalness={1} roughness={0.2} />
      </mesh>
      {/* Lamp Stem */}
      <mesh position={[0, 42, -15]}>
        <cylinderGeometry args={[0.5, 0.5, 14, 8]} />
        <meshStandardMaterial color="#d4af37" metalness={1} roughness={0.2} />
      </mesh>
      {/* Green Glass Shade */}
      <mesh position={[0, 48, -10]} rotation={[Math.PI / 4, 0, 0]}>
        <cylinderGeometry args={[4, 4, 18, 16, 1, false, 0, Math.PI]} />
        <meshPhysicalMaterial 
          color="#00ff66" 
          emissive="#00ff66" 
          emissiveIntensity={2} 
          transparent 
          opacity={0.8}
          transmission={0.9} 
          roughness={0.1}
        />
        {/* The light source itself */}
        <pointLight color="#00ff66" intensity={2} distance={100} position={[0, -2, 0]} />
      </mesh>
    </group>
  );
};

const ScalesOfJustice = ({ position }) => {
  const groupRef = useRef();
  
  useFrame((state) => {
    if (groupRef.current) {
      groupRef.current.rotation.y = state.clock.elapsedTime * 0.2;
      groupRef.current.rotation.z = Math.sin(state.clock.elapsedTime * 2) * 0.1;
    }
  });

  return (
    <group position={position} ref={groupRef} scale={2}>
      <mesh position={[0, 40, 0]}>
        <cylinderGeometry args={[1, 2, 80, 16]} />
        <meshStandardMaterial color="#d4af37" metalness={1} roughness={0.2} wireframe />
      </mesh>
      
      <mesh position={[0, 75, 0]} rotation={[0, 0, Math.PI / 2]}>
        <cylinderGeometry args={[1, 1, 60, 16]} />
        <meshStandardMaterial color="#d4af37" metalness={1} roughness={0.2} wireframe />
      </mesh>

      <mesh position={[-30, 45, 0]}>
        <cylinderGeometry args={[0.2, 0.2, 60, 8]} />
        <meshStandardMaterial color="#d4af37" wireframe />
      </mesh>
      <mesh position={[-30, 15, 0]} rotation={[Math.PI, 0, 0]}>
        <coneGeometry args={[12, 10, 16]} />
        <meshStandardMaterial color="#d4af37" wireframe />
      </mesh>

      <mesh position={[30, 45, 0]}>
        <cylinderGeometry args={[0.2, 0.2, 60, 8]} />
        <meshStandardMaterial color="#d4af37" wireframe />
      </mesh>
      <mesh position={[30, 15, 0]} rotation={[Math.PI, 0, 0]}>
        <coneGeometry args={[12, 10, 16]} />
        <meshStandardMaterial color="#d4af37" wireframe />
      </mesh>
    </group>
  );
};

const WorldLegalEagle = ({ position, rotation, visible }) => {
  

  return (
    <group visible={visible} position={position} rotation={rotation}>
      
      {/* Floor - Polished Wood */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]}>
        <planeGeometry args={[2000, 2000]} />
        <meshStandardMaterial color="#1a0d07" roughness={0.1} metalness={0.2} />
      </mesh>

      {/* Library Walls (Bookcases) */}
      <Bookcase position={[-300, 0, -200]} rotation={[0, Math.PI/4, 0]} />
      <Bookcase position={[-150, 0, -300]} rotation={[0, 0, 0]} />
      <Bookcase position={[0, 0, -300]} rotation={[0, 0, 0]} />
      <Bookcase position={[150, 0, -300]} rotation={[0, 0, 0]} />
      <Bookcase position={[300, 0, -200]} rotation={[0, -Math.PI/4, 0]} />
      
      <Bookcase position={[-400, 0, 0]} rotation={[0, Math.PI/2, 0]} />
      <Bookcase position={[400, 0, 0]} rotation={[0, -Math.PI/2, 0]} />
      
      <Bookcase position={[-300, 0, 200]} rotation={[0, Math.PI - Math.PI/4, 0]} />
      <Bookcase position={[300, 0, 200]} rotation={[0, Math.PI + Math.PI/4, 0]} />

      {/* Desks with Banker's Lamps */}
      <LibraryDesk position={[-150, 0, 0]} rotation={[0, 0, 0]} />
      <LibraryDesk position={[150, 0, 0]} rotation={[0, 0, 0]} />
      <LibraryDesk position={[-150, 0, 150]} rotation={[0, 0, 0]} />
      <LibraryDesk position={[150, 0, 150]} rotation={[0, 0, 0]} />

      {/* Ambient Law Lighting */}
      <ambientLight intensity={0.2} color="#ffeedd" />
      <pointLight position={[0, 200, 0]} intensity={1.5} color="#d4af37" distance={800} />

      {/* Rotating Wireframe Scales of Justice in the center */}
      <ScalesOfJustice position={[0, 50, -100]} />

      <Text 
        position={[0, 300, -280]} 
        fontSize={120} 
        color="#ffffff" 
        outlineWidth={0.03} 
        outlineColor="#d4af37" 
        font="/fonts/Inter-Bold.woff"
      >
        LEGAL EAGLE
      </Text>
      
      <Text 
        position={[0, 220, -280]} 
        fontSize={40} 
        color="#d4af37" 
        maxWidth={800} 
        textAlign="center"
      >
        THE PRESTIGE OF THE PAST. THE POWER OF TOMORROW.
      </Text>

    </group>
  );
};

export default WorldLegalEagle;
